#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/Xatom.h>
#include <assert.h>
#include <poll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
static Display*d;static Window root,parent,child;static Atom netstate,mh,mv,full,wmstate,change,moveresize,closeatom;static int gesture;
static void message(Window w,Atom atom,long a,long b,long c,long x,long y){XEvent e={0};e.xclient.type=ClientMessage;e.xclient.window=w;e.xclient.message_type=atom;e.xclient.format=32;e.xclient.data.l[0]=a;e.xclient.data.l[1]=b;e.xclient.data.l[2]=c;e.xclient.data.l[3]=x;e.xclient.data.l[4]=y;XSendEvent(d,root,False,SubstructureRedirectMask|SubstructureNotifyMask,&e);}
static Window create(const char*title){Window w=XCreateSimpleWindow(d,root,0,0,240,160,0,0,strstr(title,"child")?0xc04020:0x20c040);XStoreName(d,w,title);XClassHint cl={"window-peer","TramesWindowPeer"};XSetClassHint(d,w,&cl);XSelectInput(d,w,StructureNotifyMask|PropertyChangeMask|FocusChangeMask|ButtonPressMask);XSizeHints h={.flags=PMinSize|PMaxSize,.min_width=160,.min_height=100,.max_width=640,.max_height=480};XSetWMNormalHints(d,w,&h);XSetWMProtocols(d,w,&closeatom,1);return w;}
static void state(Window w){Atom type;int format;unsigned long count,after;unsigned char*bytes=NULL;int maxh=0,maxv=0,f=0;XGetWindowProperty(d,w,netstate,0,64,False,XA_ATOM,&type,&format,&count,&after,&bytes);if(bytes){Atom*a=(Atom*)bytes;for(unsigned long i=0;i<count;i++){maxh|=a[i]==mh;maxv|=a[i]==mv;f|=a[i]==full;}XFree(bytes);}XWindowAttributes a;assert(XGetWindowAttributes(d,w,&a));printf("configured %s %d %d max=%d full=%d resizing=0 active=0\n",w==parent?"parent":"child",a.width,a.height,maxh&&maxv,f);}
int main(void){setbuf(stdout,NULL);d=XOpenDisplay(NULL);assert(d);root=DefaultRootWindow(d);netstate=XInternAtom(d,"_NET_WM_STATE",False);mh=XInternAtom(d,"_NET_WM_STATE_MAXIMIZED_HORZ",False);mv=XInternAtom(d,"_NET_WM_STATE_MAXIMIZED_VERT",False);full=XInternAtom(d,"_NET_WM_STATE_FULLSCREEN",False);wmstate=XInternAtom(d,"WM_STATE",False);change=XInternAtom(d,"WM_CHANGE_STATE",False);moveresize=XInternAtom(d,"_NET_WM_MOVERESIZE",False);closeatom=XInternAtom(d,"WM_DELETE_WINDOW",False);parent=create("Trames window parent");XMapWindow(d,parent);XSync(d,False);state(parent);int done=0;while(!done){while(XPending(d)){XEvent e;XNextEvent(d,&e);Window event_window=e.type==ConfigureNotify?e.xconfigure.window:e.xany.window;if(event_window!=parent&&event_window!=child)continue;if(e.type==ConfigureNotify||(e.type==PropertyNotify&&(e.xproperty.atom==netstate||e.xproperty.atom==wmstate)))state(event_window);if(e.type==FocusIn)printf("focus %s\n",e.xfocus.window==parent?"parent":"child");if(e.type==FocusOut)printf("blur %s\n",e.xfocus.window==parent?"parent":"child");if(e.type==ButtonPress&&gesture){XUngrabPointer(d,e.xbutton.time);message(e.xbutton.window,moveresize,e.xbutton.x_root,e.xbutton.y_root,gesture=='v'?8:4,e.xbutton.button,1);printf("gesture %c\n",gesture);gesture=0;}if(e.type==ClientMessage&&e.xclient.data.l[0]==(long)closeatom)done=1;}XFlush(d);if(XEventsQueued(d,QueuedAlready))continue;struct pollfd fds[2]={{ConnectionNumber(d),POLLIN,0},{0,POLLIN,0}};assert(poll(fds,2,30000)>0);if(fds[1].revents&POLLIN){char c;assert(read(0,&c,1)==1);printf("command %c\n",c);switch(c){case 'm':case 'n':message(parent,netstate,c=='m',mh,mv,1,0);break;case 'f':case 'u':{XSizeHints hints={.flags=PMinSize|(c=='u'?PMaxSize:0),.min_width=160,.min_height=100,.max_width=640,.max_height=480};XSetWMNormalHints(d,parent,&hints);message(parent,netstate,c=='f',full,0,1,0);break;}case 'i':message(parent,change,3,0,0,0,0);break;case 'c':child=create("Trames window child");XSetTransientForHint(d,child,parent);XMapWindow(d,child);break;case 'd':XDeleteProperty(d,child,XA_WM_TRANSIENT_FOR);break;case 'x':XDestroyWindow(d,child);child=0;break;case 'v':case 'r':gesture=c;break;case 's':XResizeWindow(d,parent,300,200);break;case 'q':done=1;break;default:break;}XFlush(d);}}if(child)XDestroyWindow(d,child);XDestroyWindow(d,parent);XCloseDisplay(d);puts("window-done");return 0;}
